args.command:
cd /root/.nanobot && echo "=== config.json 顶层结构 ===" && python3 -c "
import json
with open('config.json') as f:
    d = json.load(f)
for k,v in d.items():
    if isinstance(v, dict):
        print(f'{k}: dict({len(v)} keys) -> {list(v.keys())[:5]}...')
    elif isinstance(v, list):
        print(f'{k}: list({len(v)} items)')
    else:
        print(f'{k}: {type(v).__name__} = {repr(v)[:60]}')
"
